"""Real-log case study: a scheduled task masquerading as a Windows task (OTRF SDWIN-201219070027).

Prints, straight from the raw recordings, the evidence an analyst (or HESP) would collect probe
by probe, and the contrast set of every other task creation/update in the 27 downloaded
recordings. Qualitative only: no likelihoods are estimated and nothing here is a benchmark.

Usage: python otrf_case_study.py > ../../docs/case_study_otrf_raw.md
"""
import collections
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from otrf_load import ROOT, events, manifest  # noqa: E402

CASE = "schtask_create.zip"
TASK = r"\Microsoft\Windows\SoftwareProtectionPlatform\EventCacheManager"


def tag(xml, name):
    m = re.search(rf"<{name}>(.*?)</{name}>", xml or "", re.S)
    return m.group(1).strip() if m else None


def session_of(evs, host, logon_id):
    if logon_id == "0x3e7":
        return "SYSTEM session (0x3e7)"
    for e in evs:
        if e.get("EventID") == 4624 and e.get("Hostname") == host and str(e.get("TargetLogonId")) == logon_id:
            return f"logon type {e.get('LogonType')} ({e.get('AuthenticationPackageName')}) from {e.get('IpAddress')}"
    return "logon not in recording (session began earlier)"


def main():
    sys.stdout.reconfigure(encoding="utf-8")
    evs = list(events(ROOT / "host" / CASE))
    alert = next(e for e in evs if e.get("EventID") == 4698 and e.get("TaskName") == TASK)
    host, lid, xml = alert.get("Hostname"), str(alert.get("SubjectLogonId")), alert.get("TaskContent")
    session = session_of(evs, host, lid)
    src_ip = re.search(r"from (\S+)", session).group(1) if "from" in session else None
    src_host = collections.Counter(e.get("Hostname") for e in evs
                                   if src_ip and e.get("EventID") == 5156 and src_ip in str(e)).most_common(1)
    remote_cmd = [e for e in evs if e.get("EventID") == 1 and "schtasks" in str(e.get("Image", "")).lower()
                  and TASK.lower() in str(e.get("CommandLine", "")).lower()]
    ran = [e for e in evs if e.get("EventID") == 1 and "notepad.exe" in str(e.get("Image", "")).lower()]
    L = ["# OTRF case study: raw evidence (generated by `otrf_case_study.py`)", "",
         f"Recording `{CASE}` (OTRF SDWIN-201219070027, MIT). Host `{host}`.", "",
         "| Step | Source event | Observed value |", "| --- | --- | --- |",
         f"| Alert | Security 4698 at {alert.get('@timestamp')} | task `{TASK}` created |",
         f"| Probe: creator | 4698 SubjectUserName | `{alert.get('SubjectDomainName')}\\{alert.get('SubjectUserName')}` |",
         f"| Probe: logon session | 4624 with TargetLogonId {lid} | {session} |",
         f"| Probe: task action | 4698 TaskContent | `{tag(xml, 'Command')} {tag(xml, 'Arguments')}`, "
         f"runs as `{tag(xml, 'UserId')}`, author `{tag(xml, 'Author')}` |",
         f"| Probe: source host | 5156 connections from {src_ip} | "
         f"{src_host[0][0] if src_host else 'n/a'} |",
         f"| Probe: source process | Sysmon 1 on source host | "
         + (f"`{remote_cmd[0].get('CommandLine').strip()[:140]}`" if remote_cmd else "not recorded") + " |",
         f"| Did it run? | Sysmon 1 notepad.exe | {'yes' if ran else 'not within the recording'} |", "",
         "## Contrast: every other task creation (4698) / update (4702) in the 27 recordings", "",
         "| Recording | Task | Creator | Session | Label |", "| --- | --- | --- | --- | --- |"]
    for rec in manifest():
        meta = (ROOT / "metadata" / f"{rec['id']}.yaml").read_text(encoding="utf-8", errors="replace")
        rec_evs = list(events(ROOT / "host" / rec["file"]))
        seen = set()
        for e in rec_evs:
            if e.get("EventID") not in (4698, 4702) or "security" not in str(e.get("Channel", "")).lower():
                continue
            key = (e.get("EventID"), e.get("TaskName"))
            if key in seen:
                continue
            seen.add(key)
            leaf = str(e.get("TaskName")).rsplit("\\", 1)[-1]
            label = "attack" if re.search(rf"\b{re.escape(leaf)}\b", meta) else "background"
            L.append(f"| {rec['file'][:34]} | `{e.get('TaskName')}` ({'new' if e.get('EventID') == 4698 else 'update'}) "
                     f"| {e.get('SubjectUserName')} | {session_of(rec_evs, e.get('Hostname'), str(e.get('SubjectLogonId')))} "
                     f"| {label} |")
    print("\n".join(L))


if __name__ == "__main__":
    main()
